-- ----------------------------
-- Table structure for t_moment
-- ----------------------------
DROP TABLE IF EXISTS `t_moment`;
CREATE TABLE `t_moment`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT,
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '说说内容',
  `image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '可选配图',
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_moment
-- ----------------------------
INSERT INTO `t_moment` VALUES (9, '今天把小工具入口从导航栏移到了右下角浮窗，参考了 ChatGPT 的设计模式，感觉博客一下子现代了不少。不过 iframe 加载的坑真不少——v-show 隐藏时 load 事件根本不触发，最后用 loading 遮罩层 + 20s 超时降级才搞定。', NULL, '2026-05-25 10:30:00');
INSERT INTO `t_moment` VALUES (10, '旅行助手联调踩了一天的坑：axios 超时 180s 不够 → 改 300s；LLM 4 次串行调用 → ThreadPoolExecutor 并行化；前后端类型对不上 → 统一嵌套 location。最隐蔽的是 v-model=\"[activeSection]\" 这种语法 Vite 直接编译不过...', NULL, '2026-05-26 18:20:00');
INSERT INTO `t_moment` VALUES (11, '今天给旅行助手加了跨天去重 + 替补景点逻辑，四层防线：Prompt 约束 → 后处理去重 → 两级补位 → 替补标记。顺手把 blog-server 16 个类的构造器全换成了 @RequiredArgsConstructor，净减少 37 行样板代码，清爽！', NULL, '2026-05-27 17:45:00');
INSERT INTO `t_moment` VALUES (12, '旅行助手性能优化完成！天气 Agent 删掉改用纯代码（-1 LLM 调用），Prompt 全部 compact 化，input token 从 8000 降到 3500，减少 56%！最大的感悟：能用代码的就别用 LLM，每一行 prompt 都在烧钱。', NULL, '2026-05-28 17:50:00');
INSERT INTO `t_moment` VALUES (13, 'Docker 多阶段构建 + Compose 四服务编排 + Nginx 反向代理 + GitHub Actions CI/CD 全部调通。docker-compose up -d 一键启动整个项目的感觉太爽了！遇到一个坑：GitHub 443 被墙，得给 git 配 http.proxy。', NULL, '2026-06-01 12:10:00');
INSERT INTO `t_moment` VALUES (14, '今天给博客加了五层防护：全局异常处理从 3 种扩展到 12 种、所有实体加 Jakarta Validation、Redis 缓存配好 CacheManager、自定义 @RateLimit 注解做限流、AOP 审计日志覆盖 16 个管理方法。面试问到生产级防护这块完全不虚了。', NULL, '2026-06-01 16:30:00');
INSERT INTO `t_moment` VALUES (15, '工程化三件套完成：Pinia 替代 localStorage 管理 token/用户/主题、TypeScript 搭好基础设施（strict mode + 路径别名）、ESLint flat config 前后端各一份。后端也补了 14 个单元测试，Mockito + H2 内存库，0 失败！', NULL, '2026-06-01 18:45:00');
INSERT INTO `t_moment` VALUES (16, '三个博客刚需功能完工：评论区支持楼中楼回复（单层嵌套）、文章时间轴归档页（SQL GROUP BY + timeline CSS）、@Async 操作审计日志（CallerRunsPolicy 兜底不丢消息）。每一项约 3-4 个文件改动，后端保正确，前端做体验。', NULL, '2026-06-02 11:00:00');
INSERT INTO `t_moment` VALUES (17, '33 tests passed！文章点赞（Redis Set 去重 + INCR 计数）、ES IK 分词搜索（title^3 + multi_match）、Prometheus + Grafana 五面板监控看板全搞定。ES 搜索还有条件装配 + MySQL LIKE 降级，dev 环境没 ES 也能正常工作。', NULL, '2026-06-02 17:25:00');
INSERT INTO `t_moment` VALUES (18, '花了一下午把 API 黑盒测试套件搭起来了，pytest + requests 59 个用例，覆盖公开/认证/管理所有端点。意外发现 Sa-Token 7 个安全漏洞——/api/admin/** 居然没被拦截！52 passed + 7 xfailed。Java 测\"内部怎么算\"，Python 测\"对外怎么响应\"，完美互补。', NULL, '2026-06-02 20:10:00');
INSERT INTO `t_moment` VALUES (19, '纯 JDK 实现图片压缩上传：javax.imageio + java.awt，零外部依赖！JPEG Quality 80% BICUBIC 插值，4000px 照片压到 1920px，5MB→380KB，自动生成 400px 缩略图。GIF 跳过压缩保留动画、透明 PNG 保持 ARGB、压缩失败静默回退原图。', NULL, '2026-06-10 14:20:00');
INSERT INTO `t_moment` VALUES (20, '缓存三级防护全部实现：防穿透（空值标记 __CACHE_NULL__ TTL 5min）、防雪崩（随机 TTL 30~40min）、防击穿（Redisson 分布式锁 + Double-Check）。自定义 @CacheShield 注解完全替代 Spring @Cacheable，AOP 切面集中管理所有防护逻辑。33 tests passed！', NULL, '2026-07-03 15:20:00');
INSERT INTO `t_moment` VALUES (21, 'Redis 两个高级数据结构一起上：ZSet 做点赞排行榜（ZINCRBY 增量维护 + ZREVRANGE 取 Top-N），Stream 升级操作审计（消费者组 + ACK + 批量写入）。Windows Redis 3.x 不支持 Stream 自动降级为 @Async。实操下来 ZSet 比 MySQL ORDER BY count 优雅太多了！', NULL, '2026-07-03 18:30:00');
INSERT INTO `t_moment` VALUES (22, 'RAG 智能问答系统上线！ES IK 检索 + DeepSeek 流式生成 + SSE 推送前端，右下角浮窗和工具箱并排显示。Python FastAPI 微服务独立于 Java，复用旅行助手的 OpenAI SDK 模式。最坑的是 Nginx proxy_buffering off——不加这行 SSE 完全没流式效果。', NULL, '2026-07-21 09:15:00');
INSERT INTO `t_moment` VALUES (23, '博客前后台大翻新：前台从蓝色玻璃拟态改成知识库式低噪音网格背景，主色 #2563eb 更克制；后台从展示面板升级为深色侧栏 + 白色顶栏的专业 CMS 工作台。设计原则：不是加更多装饰，而是减到刚好够用。npm run build 两端都通过！', NULL, '2026-07-21 12:40:00');
INSERT INTO `t_moment` VALUES (24, '修了一个隐蔽的前端 bug：仪表盘四个统计数字全显示 0，但列表页数据正常。根因是 Promise.all 一个接口失败整组都挂。改成 Promise.allSettled + 单模块降级兜底就好了。一个单词的改动，但背后是\"要么全对要么全错\"到\"各负其责\"的思维转变。', NULL, '2026-07-21 16:20:00');

-- ----------------------------
-- Table structure for t_operation_log
-- ----------------------------
DROP TABLE IF EXISTS `t_operation_log`;
CREATE TABLE `t_operation_log`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT,
  `username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '操作人',
  `ip` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '操作IP',
  `operation` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '操作描述',
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '操作类型: CREATE/UPDATE/DELETE/OTHER',
  `method_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '方法名',
  `args` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '请求参数(截断)',
  `execution_time` bigint(0) NULL DEFAULT NULL COMMENT '执行耗时(ms)',
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 39 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;

